using System;using System.Linq;using System.Collections.Generic;
using HeartOfTheRain.App.Home;
namespace HeartOfTheRain.App.Profile {
    public static class RainCupDesignLayout {
        const string Navy="#163A61",Muted="#708497",Cream="#FFF4D7";
        static string T(string k)=>RainCupDesignText.T(k);
        static void Add(HomeFrame f,string id,string parent,string kind,string value,float x,float y,float w,float h,int font=14,string color=Navy,bool sliced=false){var e=new HomeElement{id=id,parent=parent,kind=kind,x=x,y=y,width=w,height=h,fontSize=font,color=color,sliced=sliced,preserveAspect=!sliced};if(kind=="text")e.text=value;else if(kind=="sprite"){e.asset=value;e.color="#FFFFFF";}else e.action=value;f.elements.Add(e);}
        public static string Action(RainCupView v){var s=v.snapshot;return v.error?"retry":s==null||s.state=="Unavailable"?"close":s.state=="Finished"?"claim":s.state=="Claimed"?"close":s.canJoin?"join":s.state=="Active"&&s.completed<50?"play":"disabled";}
        public static HomeFrame Build(float width,float height,RainCupView v){
            var s=v.snapshot??new RainCupSnapshot();bool unavailable=s.state=="Unavailable",error=v.error||unavailable,locked=s.state=="Locked",active=s.state=="Active",finished=s.state=="Finished",claimed=s.state=="Claimed";
            float w=Math.Max(320,width),h=Math.Max(300,height);bool wide=w>=650&&h<=550;float pw=Math.Min(wide?720:440,w-24),pad=pw<=321?17:20,bw=pw-2*pad;bool small=pw<=321;float heroH=116,introH=wide?20:34;
            var rivals=s.run==null?new int[0]:RainCupModel.RivalScores(s.run,s.observedNow);var rows=new List<KeyValuePair<int,int>>();if(s.run!=null){rows.Add(new KeyValuePair<int,int>(-1,s.run.points));for(int i=0;i<rivals.Length;i++)rows.Add(new KeyValuePair<int,int>(i,rivals[i]));rows=rows.OrderByDescending(r=>r.Value).ThenBy(r=>r.Key).ToList();}
            int rank=s.run==null?0:active?RainCupModel.Rank(s.run.points,rivals):s.run.finalRank;int count=v.showPrizes?(s.rules?.rankRewards.Length??0):rows.Count;float rh=small?57:56,listH=count==0?267:count*rh+Math.Max(0,count-1)*5;
            float heroW=wide?bw*.4f-9:bw,listX=wide?heroW+18:0,listW=wide?bw-heroW-18:bw,listY=wide?introH:introH+heroH+12,bodyH=error?155:wide?introH+Math.Max(heroH,73+listH)+4:listY+73+listH+4;
