            Add(f,"panel","","group","",(w-pw)/2,py,pw,ph);Add(f,"shell","panel","sprite","DG_Chrome",0,0,pw,ph,sliced:true);Add(f,"header","panel","group","",0,0,pw,67);
            string title=T("title");Add(f,"title","header","text",title,40,0,pw-80,57,title.Length>14?(small?22:24):small?27:30,Cream);Add(f,"close","header","group","close",pw-52,-32,46,46);Add(f,"close-art","close","sprite","DG_Close",-2.3f,-2.3f,50.6f,50.6f);
