            if(!error){
                Add(f,"hero","body","group","",0,introH,heroW,heroH);Add(f,"hero-well","hero","sprite","DG_Hero",0,0,heroW,heroH,sliced:true);float left=heroW*.43f,right=heroW-left-12;
                Add(f,"trophy","hero","sprite","RC_Trophy",4,5,left-4,heroH-10);
                if(active){Add(f,"hero-label","hero","text",T("score"),left,3,right,22,12,"#8A6B38");Add(f,"score-count","hero","text",s.run.points.ToString(),left,25,right,37,small?31:36);Add(f,"rank-summary","hero","text",RainCupDesignText.Rank(rank,rows.Count),left,62,right,20,11,"#4D7A3B");Add(f,"timer","hero","text",RainCupText.Timer(v.remaining),left,82,right,18,12,Muted);}
                else if(locked){int target=s.rules.unlockClears;Add(f,"hero-title","hero","text",RainCupText.T("Complete {0} levels to unlock").Replace("{0}",target.ToString()),left,2,right,43,small?16:18);Add(f,"score-count","hero","text",s.completed+" / "+target,left,44,right,29,small?25:30);Add(f,"progress-track","hero","sprite","WW_Track",left,77,right,16,sliced:true);float fillWidth=(right-6)*Math.Max(0,Math.Min(1,s.completed/(float)Math.Max(1,target)));Add(f,"progress-clip","hero","group","",left+3,80,fillWidth,10);Add(f,"fill","progress-clip","sprite","WW_Fill",0,0,Math.Max(12,fillWidth),10,sliced:true);Add(f,"hero-note","hero","text",RainCupDesignText.N("unlockNote",Math.Max(0,target-s.completed)),left,94,right,18,10,Muted);}
                else{string key=finished?"resultTitle":claimed?"collectedTitle":s.state=="Exhausted"?"All levels completed":"readyTitle";Add(f,"hero-title","hero","text",T(key).Replace("{rank}",rank.ToString()),left,9,right,48,small?17:20,claimed?"#4C7A3D":Navy);string note=finished?"resultNote":claimed?"collectedNote":"readyNote";Add(f,"hero-note","hero","text",T(note),left,62,right,40,11,Muted);}
                Add(f,"competition","body","group","",listX,listY,listW,73+listH);Add(f,"tabs-track","competition","sprite","RC_Track",0,0,listW,44,sliced:true);float tw=(listW-9)/2;
                for(int i=0;i<2;i++){bool selected=v.showPrizes==(i==1);string id=i==0?"standings":"rewards";Add(f,id,"competition","group",id,3+i*(tw+3),3,tw,38);if(selected)Add(f,id+"-art",id,"sprite","RC_Tab",0,0,tw,38,sliced:true);Add(f,id+"-label",id,"text",T(id),6,0,tw-12,38,small?13:15,selected?Cream:"#637D91");}
