                    Add(f,id,"competition","group","",0,73+i*(rh+5),listW,rh);Add(f,id+"-card",id,"sprite",me||mine&&claimed?"DG_Collected":v.showPrizes&&position==1||mine?"DG_Today":"DG_Upcoming",0,0,listW,rh,sliced:true);
                    float inset=small?9:12,badge=small?30:35,avatar=small?37:42,gap=small?6:8;string medal=position==1?"RC_Gold":position==2?"RC_Silver":position==3?"RC_Bronze":null;if(medal!=null)Add(f,"medal-"+i,id,"sprite",medal,inset,(rh-42)/2,badge,42);Add(f,"rank-"+i,id,"text",position.ToString(),inset,medal==null?8:4,badge,37,medal==null?18:20);
                    float x=inset+badge+gap;
                    if(!v.showPrizes){Add(f,"avatar-"+i,id,me?"avatar":"sprite",me?"":"RC_Rival",x,(rh-avatar)/2,avatar,avatar);if(me)Add(f,"avatar-frame-"+i,id,"sprite","RC_Frame",x,(rh-avatar)/2,avatar,avatar);x+=avatar+gap;float score=small?42:48,nameW=listW-inset-score-gap-x;Add(f,"name-"+i,id,"text",me?(string.IsNullOrEmpty(v.playerName)?T("player"):v.playerName):string.Format(RainCupText.T("Simulated {0}"),rows[i].Key+1),x,7,nameW,me?26:rh-14,small?13:15,me?"#3D6C36":Navy);if(me)Add(f,"you-"+i,id,"text",T("you"),x,32,nameW,17,10,"#4B773E");Add(f,"points-"+i,id,"text",rows[i].Value.ToString(),listW-inset-score,5,score,29,small?20:22,me?"#437638":Navy);Add(f,"points-label-"+i,id,"text",T("points"),listW-inset-score,33,score,17,9,Muted);}
                    else{var rewards=WellworksDesignLayout.Rewards(s.rules.rankRewards[i]);float rw=listW-x-inset,cell=rw/Math.Max(1,rewards.Count);Add(f,"rewards-"+i,id,"group","",x,0,rw,rh);for(int j=0;j<rewards.Count;j++){var r=rewards[j];float icon=small?29:34,iw=r.Key=="DG_Rocket"?icon*39/34:icon,qw=r.Value>=100?36:21,total=iw+3+qw,rx=j*cell+(cell-total)/2;Add(f,"reward-item-"+i+"-"+j,"rewards-"+i,"group","",j*cell,0,cell,rh);Add(f,"reward-"+i+"-"+j,"reward-item-"+i+"-"+j,"sprite",r.Key,rx-j*cell,(rh-icon)/2,iw,icon);Add(f,"quantity-"+i+"-"+j,"reward-item-"+i+"-"+j,"text",(r.Key=="DG_Coin"?"":"×")+r.Value,rx-j*cell+iw+3,8,qw,rh-16,small?16:18);}if(mine&&claimed)Add(f,"collected-check-"+i,id,"sprite","DG_Check",listW-22,-4,17,17);}
                }
            }
            Add(f,"footer","panel","group","",pad,ph-footerH-18,bw,footerH);string action=Action(v),label=action=="retry"?RainCupText.T("Please try again"):action=="close"?T(error?"close":"done"):action=="join"?T("join"):action=="play"?T("play"):action=="claim"?T("claim"):T(locked?"locked":"All levels completed");float buttonW=wide?Math.Min(365,bw):bw-6;
            float buttonH=wide?50:58;Add(f,"primary","footer","group",action,(bw-buttonW)/2,wide?5:9,buttonW,buttonH);Add(f,"primary-art","primary","sprite","DG_Primary",0,0,buttonW,buttonH,sliced:true);Add(f,"primary-label","primary","text",label,15,0,buttonW-30,buttonH,wide?22:small?23:25,"#FFFFFF");
            Add(f,"status","footer","text",v.actionError?T("error"):v.received?T("claimedNotice"):T("rule"),4,wide?62:73,bw-8,wide?22:29,small?9:10,Muted);return f;
        }
    }
